  const manifest={schemaVersion:'product-line/1',id:'fixture-hooks',version:'1.0.0',tools:[],hooks:[{manifest:'hooks/host-policy.ts',event:'verify.hostCommand',order:5},{manifest:'hooks/device-command-tree.ts',event:'verify.deviceCommand',order:10},{manifest:'hooks/host-destructive.ts',event:'verify.hostCommand',order:10},{manifest:'hooks/workbook-contract.ts',event:'verify.workbook',order:10}],flows:['flows/execute.json']};
  for(const [path,value]of [['product-line.json',manifest],['flows/execute.json',{schema:'circle-packs/flow/1',id:capabilityPackId,version:`${capabilityPackId}/1`}]] as const){const bytes=Buffer.from(JSON.stringify(value));files.push({path,base64:bytes.toString('base64'),sha256:sha256(bytes)});}files.sort((a,b)=>a.path<b.path?-1:1);const module={id:manifest.id,kind:'product-line',root:`products/${manifest.id}`,manifestPath:`products/${manifest.id}/product-line.json`,version:manifest.version,files:files.map(({path,sha256})=>({path,sha256})),digest:sha256(files.map(file=>`${file.sha256}  ${file.path}\n`).join(''))};return {module,files};
